<script>
(function () {
  var tabs = document.querySelectorAll('#category-tabs .tl-tab');
  var cards = document.querySelectorAll('#product-grid .tl-product');
  var status = document.getElementById('tab-status');
  if (!tabs.length || !cards.length) { return; }

  function showCategory(cat) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = cat === 'All' || card.getAttribute('data-category') === cat;
      card.hidden = !match;
      if (match) { shown += 1; }
    });
    tabs.forEach(function (tab) {
      tab.setAttribute('aria-pressed', tab.getAttribute('data-filter') === cat ? 'true' : 'false');
    });
    if (status) {
      status.textContent = 'Showing ' + shown + ' product' + (shown === 1 ? '' : 's');
    }
  }

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      showCategory(tab.getAttribute('data-filter'));
    });
  });

  showCategory('All');
})();
</script>
